const LOGOS = "<img class=\"sf9-logo\" alt=\"DepEd\" src=\"data:image/png;base64,\" style=\"left:10.66px;top:14.59px;width:89.73px;height:85.83px\"><div class=\"sf9-logo\" style=\"left:575.51px;top:16.59px;width:97.63px;height:92.33px;overflow:hidden\"><img alt=\"School logo\" src=\"data:image/png;base64,\" style=\"position:absolute;left:0;top:-7.95px;width:104.55px;height:108.15px\"></div>";
const BANK = {"Mahusay-1": "Mahusay ang pagganap. Ipagpatuloy ang kasipagan at magandang asal.", "Mahusay-2": "Napakahusay ng ipinakitang pag-unlad sa pag-aaral.", "Mahusay-3": "Aktibong nakikilahok sa mga gawain at nagpapakita ng magandang saloobin.", "Mahusay-4": "Masipag, responsable, at palaging nagsisikap na matuto.", "Mahusay-5": "Patuloy na nagpapakita ng kahusayan sa mga gawain.", "Mahusay-6": "Mahusay makipagtulungan at nakikibahagi sa mga gawain sa klase.", "Mahusay-7": "Nagpapakita ng tiwala sa sarili at kahandaang matuto.", "Mahusay-8": "Mahusay na naisasagawa ang mga gawain at sumusunod sa mga panuto.", "Mahusay-9": "Maganda ang pag-unlad at pagganap sa mga nakaraang gawain.", "Mahusay-10": "Ipagpatuloy ang sipag, tiyaga, at positibong saloobin sa pag-aaral.", "Patuloy na Umunlad-1": "Patuloy na umuunlad at nagpapakita ng magandang pagsisikap.", "Patuloy na Umunlad-2": "Maganda ang pag-unlad. Ipagpatuloy ang pagsasanay.", "Patuloy na Umunlad-3": "Unti-unting nahuhubog ang mga kasanayan sa pag-aaral.", "Patuloy na Umunlad-4": "Nagpapakita ng pagsisikap sa pagsasagawa ng mga gawain.", "Patuloy na Umunlad-5": "Patuloy na pagbutihin ang mga kasanayan upang higit pang umunlad.", "Patuloy na Umunlad-6": "May magandang potensyal at patuloy na nagpapakita ng pag-unlad.", "Patuloy na Umunlad-7": "Mas lalo pang uunlad sa pamamagitan ng regular na pagsasanay.", "Patuloy na Umunlad-8": "Nagpapakita ng positibong pagbabago sa pagkatuto.", "Patuloy na Umunlad-9": "Patuloy na nagsisikap at nakikilahok sa mga gawain.", "Patuloy na Umunlad-10": "Ipagpatuloy ang pagsisikap upang higit pang mapaunlad ang kakayahan.", "Nangangailangan ng Karagdagang Pagsisikap-1": "Nangangailangan pa ng higit na pagsasanay at paggabay.", "Nangangailangan ng Karagdagang Pagsisikap-2": "Hinihikayat na magsikap pa upang mapaunlad ang mga kasanayan.", "Nangangailangan ng Karagdagang Pagsisikap-3": "Kailangan ng regular na pagsasanay upang higit na matuto.", "Nangangailangan ng Karagdagang Pagsisikap-4": "Patuloy na nangangailangan ng gabay sa pagsasagawa ng mga gawain.", "Nangangailangan ng Karagdagang Pagsisikap-5": "Hinihikayat na maging mas aktibo sa mga gawain sa klase.", "Nangangailangan ng Karagdagang Pagsisikap-6": "Makabubuting dagdagan ang oras sa pagsasanay at pag-aaral.", "Nangangailangan ng Karagdagang Pagsisikap-7": "May kakayahang umunlad sa patuloy na paggabay at pagsisikap.", "Nangangailangan ng Karagdagang Pagsisikap-8": "Kailangan ng higit na pagtutok upang mapahusay ang pagkatuto.", "Nangangailangan ng Karagdagang Pagsisikap-9": "Patuloy na hikayatin at suportahan upang mapaunlad ang kakayahan.", "Nangangailangan ng Karagdagang Pagsisikap-10": "Sa tuloy-tuloy na pagsisikap at pagsasanay, higit pang uunlad ang pagganap."};
const BANDS = [[60.0, "Nangangailangan ng Karagdagang Pagsisikap"], [75.0, "Patuloy na Umunlad"], [90.0, "Mahusay"]]; // [minGrade, category] sorted ascending (Grade Bands sheet)

const SUBJECTS = {34:'Effective Communication',35:'Mabisang Komunikasyon',36:'General Mathematics',37:'General Science',38:'Life and Career Skills',39:'Pag-aaral ng Kasaysayan at Lipunang Pilipino'};
const num = v => (v === '' || v === null || v === undefined || isNaN(Number(v))) ? null : Number(v);
const avg = a => a.reduce((s,x)=>s+x,0)/a.length;
const xround = n => n === null ? '' : String(Math.sign(n)*Math.round(Math.abs(n)));   // Excel "0" format (half away from zero)
const remark = n => n===null ? '' : (n>=75&&n<=100 ? 'Passed' : (n>=60&&n<75 ? 'Failed' : ''));

function termComment(vals, lrn){                       // mirrors Q15 / Q19 / Q23 formulas
  const v = vals.map(num).filter(x=>x!==null);
  if (v.length < 6) return '';
  const a = avg(v);
  let cat = null; for (const [min,name] of BANDS) if (a >= min) cat = name;   // VLOOKUP approx. match
  if (!cat || !/^\d+$/.test(String(lrn||''))) return '';
  const k = Number(String(lrn).slice(-1)) + 1;                                 // MOD(LRN,10)+1
  return BANK[cat+'-'+k] || '';
}

export function computeSF9(d){
  const f = {}; const g = {};
  const att = d.attendance || {};
  f.name=d.name||''; f.age=d.age??''; f.sex=d.sex||''; f.lrn=d.lrn||''; f.grade=d.grade??''; f.section=d.section||''; f.track=d.track||'';
  for (let i=0;i<12;i++){
    const m=(att.months||[])[i]??'', cd=(att.classDays||[])[i], ab=(att.absent||[])[i];
    f['month'+i]=m; f['days'+i]=cd??''; f['absent'+i]=ab??'';
    f['present'+i]=(num(cd)===null||num(ab)===null)?'':String(num(cd)-num(ab));
  }
  for (const r of [34,35,36,37,38,39]) for (const t of [1,2,3]){
    const x=num(((d.grades||{})[SUBJECTS[r]]||{})[t]); g[r+'_'+t]=x; f['g'+r+'_'+t]=x===null?'':xround(x);
  }
  const el=d.electives||[];
  [41,42,43].forEach((r,i)=>{ const e=el[i]||{}; f['elective'+r]=e.name||''; const x=num(e.grade); g[r+'_'+(r-40)]=x; f['g'+r+'_'+(r-40)]=x===null?'':xround(x); });
  const pair=t=>{const a=g['34_'+t],b=g['35_'+t]; return (a!==null&&b!==null)?avg([a,b]):null;};
  const T={1:pair(1),2:pair(2),3:pair(3)};
  for (const t of [1,2,3]) f['avg32_'+t]=T[t]===null?'':xround(T[t]);
  const fin={};
  const rowFinal=r=>{const v=[1,2,3].map(t=>g[r+'_'+t]).filter(x=>x!==null&&x!==undefined); return v.length>=3?avg(v):null;};
  fin[34]=rowFinal(34); fin[35]=rowFinal(35);
  const f3234=[fin[34],fin[35]].filter(x=>x!==null); fin[32]=f3234.length?avg(f3234):null;
  for (const r of [36,37,38,39]) fin[r]=rowFinal(r);
  fin[41]=g['41_1']??null; fin[42]=g['42_2']??null; fin[43]=g['43_3']??null;
  for (const r of [32,34,35,36,37,38,39,41,42,43]){ f['final'+r]=xround(fin[r]); f['rem'+r]=remark(fin[r]); }
  const gaSet=[fin[32],fin[36],fin[37],fin[38],fin[39],fin[41],fin[42],fin[43]];
  const ga=gaSet.every(x=>x!==null)?avg(gaSet):null;
  f.final45=xround(ga); f.rem45=ga===null?'':(ga>=75&&ga<=100?'Promoted':(ga>=60&&ga<75?'Failed':''));
  f.comment1=termComment([T[1],g['36_1'],g['37_1'],g['38_1'],g['39_1'],g['41_1']],d.lrn);
  f.comment2=termComment([T[2],g['36_2'],g['37_2'],g['38_2'],g['39_2'],g['42_2']],d.lrn);
  f.comment3=termComment([T[3],g['36_3'],g['37_3'],g['38_3'],g['39_3'],g['43_3']],d.lrn);
  return f;
}

export function renderSF9(container, data){
  container.innerHTML = '<div class="sf9-sheet">'+TEMPLATE+LOGOS+'</div>';
  const f = computeSF9(data||{});
  container.querySelectorAll('[data-f]').forEach(el=>{ el.textContent = f[el.dataset.f] ?? ''; });
  if (data && data.schoolYear) container.querySelectorAll('td').forEach(td=>{ if (td.textContent.startsWith('School Year:')) td.textContent = 'School Year: ' + data.schoolYear; });
  return container.firstElementChild;
}
/** Same as renderSF9 but returns an HTML string (for pages that return markup, like this portal's router). */
export function sf9Html(data){
  const d = document.createElement('div');
  renderSF9(d, data);
  return d.innerHTML;
}
export const SF9_CORE = Object.values(SUBJECTS);
